from lib import *
S = SS('l19')
steps = [
    step("先造一个乱七八糟的仓库:30 个版本用 --window=0 --depth=0 打成一个差的 pack(没有任何 delta);另一个 pack 里放着一个不可达的提交 X(tmp 分支的提交,分支已删、reflog 已清);再有 7 个松散对象(2 个新提交的对象加一个不可达的 blob UB)。起点:松散 7 个、2 个 pack(合计 301,898 字节)、X 与 UB 都存在;git count-objects -v:count: 7、in-pack: 93、packs: 2。", t=tl(S(1)), mark=lidx(S(1), '不可达的提交 X', 'count: 7'), done=lidx(S(1), 'in-pack: 93', 'packs: 2'), kv=KV([['pack 1', '30 个版本,没有 delta,约 300 KB'], ['pack 2', '含不可达的提交 X'], ['松散', '7 个,其中 UB 是不可达的 blob']], ['pack 2'])),
    step("把这份起点复制七份,分别执行不同的 repack。表中看四件事:松散对象数、pack 数与大小、不可达的 X、UB 的去留。git repack(无选项):松散还是 7,pack 变成 3 个(新增一个装松散对象的 pack,合计 312,259 字节);-d:松散降到 1(只剩不可达的 UB),pack 仍是 3 个;-a -d:合成 1 个 pack,81,689 字节,X 没了,UB 还在;-A -d:1 个 pack,但松散对象 4 个——X 的 3 个对象被“炸”回松散,加上 UB;-a -d -k:松散 0,X 和 UB 都被收进 pack;-a -d --cruft:2 个 pack(含一个 cruft pack),松散 0,X 与 UB 都留着。", t=tl(S(2)), mark=lidx(S(2), 'git repack -a -d  ', 'git repack -A -d', 'git repack -a -d -k', '--cruft'), done=lidx(S(2), '(起点)', 'git repack  ', 'git repack -d '), b=bars([['(起点)', 301898, '301,898'], ['git repack -a -d', 81689, '81,689'], ['git repack -a -d -f', 19756, '19,756']], 301898, mark=[2], done=[0, 1]), kv=KV([['无选项', '只把松散对象打进新 pack,旧的都留着'], ['-d', '删除已被收进 pack 的松散对象'], ['-a', '所有可达对象合成一个 pack,旧 pack 的不可达对象丢弃'], ['-A / -k / --cruft', '不可达对象分别变松散 / 收进 pack / 进 cruft pack']], ['-a'])),
    step("-f 的区别:起点的 pack 是 --window=0 --depth=0 打的,完全没有 delta,合计 301,898 字节。-a -d 重新打包后 81,689 字节(重新打包时对没有 delta 的对象做了 delta 搜索);加上 -f(--no-reuse-delta,丢弃已有 delta 全部重算)后是 19,756 字节,不到前者的四分之一。", t=tl(S(3)), mark=lidx(S(3), '起点合计'), done=lidx(S(3), '起点合计'), b=bars([['起点', 301898, '301,898'], ['-a -d', 81689, '81,689'], ['-a -d -f', 19756, '19,756']], 301898, mark=[2], done=[0, 1]), kv=KV([['不加 -f', '81,689 字节'], ['-f', '19,756 字节,重算全部 delta'], ['代价', '-f 慢,要重做所有对象的 delta 搜索']], ['-f'])),
    step("-a 与 -A 对 pack 里不可达的 X:-a -d 之后 X 没了(旧 pack 被删,X 只在旧 pack 里,不会写进新 pack),松散对象 1 个(UB);-A -d 之后 X 还在,松散对象 4 个(X 的 commit、tree、blob 三个被还原成松散对象,加上 UB);--cruft 之后 X 还在,松散对象 0 个,cruft 文件 1 个。-A 与 --cruft 都给不可达对象留了生路,等 prune 或 cruft 过期再清理。", t=tl(S(4)), mark=lidx(S(4), 'git repack -a -d  '), done=lidx(S(4), '-A -d', '--cruft'), kv=KV([['-a', '丢弃旧 pack 里的不可达对象(危险)'], ['-A', '把它们变成松散对象,等 prune'], ['--cruft', '把它们放进单独的 cruft pack(带 mtime)']], ['-a'])),
    step("--cruft 的结果:pack 目录里除了一个正常的 pack(81,689 字节,100 个对象的 .idx 3,760 字节)外,还有一个很小的 cruft pack:321 字节的 .pack、1,184 字节的 .idx、68 字节的 .rev,以及多出来的 68 字节 .mtimes——记录每个不可达对象的修改时间,过期判断靠它。count: 0,in-pack: 100,packs: 2。", t=tl(S(5)), mark=lidx(S(5), 'mtimes'), done=lidx(S(5), '321 pack-<hash>.pack', '81689 pack-<hash>.pack', 'in-pack: 100'), kv=KV([['.mtimes', '每个不可达对象的时间戳'], ['cruft pack', '321 字节,装着 X 与 UB'], ['为什么', '不用松散对象就能给不可达对象计时']], ['.mtimes'])),
]
A = mkarti('l19', 19, 'Git,repack,gc,cruft,delta,真实验证,动画演示',
    '把同一个乱七八糟的仓库(差的 pack、含不可达提交的 pack、7 个松散对象)复制七份分别 repack:无选项只新增一个 pack,-d 清掉被收进 pack 的松散对象,-a -d 合成 1 个 pack 但丢掉 pack 里的不可达提交,-A 把它们变成松散对象,-k 收进 pack,--cruft 放进带 .mtimes 的 cruft pack;-f 把 81,689 字节压到 19,756 字节。',
    'git repack 的 -a、-d、-f 到底各改变什么?这篇把同一个起点复制七份,每份用一组选项,记录松散对象数、pack 数和大小、不可达对象的去向,还看了 cruft pack 的文件结构。',
    [('丢弃', '-a -d 之后 pack 里不可达的提交 X 没了;-A、-k、--cruft 都保住了它'), ('81,689 → 19,756', '同一个没有 delta 的起点,-a -d 与 -a -d -f 重新打包后的字节数'), ('.mtimes', 'cruft pack 额外的文件,记录不可达对象的时间戳')],
    [('无选项', '<p><code>git repack</code> 只把还没进 pack 的可达对象打成一个新 pack,旧 pack 与松散对象都不动。多跑几次就会得到一堆小 pack。</p>'),
     ('-d', '<p><code>-d</code> 之后删除变得多余的东西:已经被收进 pack 的松散对象,以及内容被完全包含的旧 pack。不可达的松散对象没有被打包,所以保留。</p>'),
     ('-a 与 -A', '<p><code>-a</code> 把所有可达对象重新合成一个 pack;配合 <code>-d</code> 删掉旧 pack,旧 pack 里<b>不可达</b>的对象就这样消失了。<code>-A</code> 则把这些不可达对象还原成松散对象,留给之后的 <code>prune</code> 按过期时间清理。<code>-k</code> 把它们一起收进新 pack。</p>'),
     ('-f', '<p><code>-f</code>(<code>--no-reuse-delta</code>)让 pack-objects 丢弃已有的 delta 选择、全部重算。本例从一个完全没有 delta 的起点出发,不加 <code>-f</code> 得到 81,689 字节,加 <code>-f</code> 得到 19,756 字节。代价是 <code>-f</code> 要重做所有对象的 delta 搜索,慢得多。</p>'),
     ('cruft pack', '<p><code>--cruft</code> 把不可达对象放进一个专门的 pack,并用 <code>.mtimes</code> 文件记录每个对象的时间,不再需要为每个不可达对象保留一个松散文件。过期清理时按 <code>.mtimes</code> 判断,不用逐个看文件时间。</p>')],
    steps,
    [ENV_I_GIT + '(pack.threads=1,单线程,结果可复现;我在没固定线程数时发现 -a -d -f 的结果在两次运行间会不同,所以固定了)。七个命令都在同一份起点的复制上各运行一次;起点由 git repack -adf --window=0 --depth=0、git repack -d、git branch -D 与 git reflog expire 构造;X 是 tmp 分支上的一个提交(含 3 个对象),UB 是 git hash-object -w 写入的松散 blob',
     '没有验证:-a -d 不加 -f 的结果小于起点、却大于 -f 的原因(只记录现象);-l(跳过 alternates)、--geometric、-b(位图)、--unpack-unreachable 等其它选项;--cruft-expiration 的过期行为(见 prune 一篇);多个 pack 带 .keep 文件时的行为'],
    'repack 的选项')
